?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Histórico</title><link rel="stylesheet" href="/assets/css/base.css"><link rel="stylesheet" href="/assets/css/historico.css"></head><body><div class="app-shell"><?php renderTopbar('professor','historico');?><main class="app-main"><div class="hist-wrap"><h1>Histórico de ocorrências</h1><form class="hist-filters"><label>Laboratório <select name="lab"><option value="">Todos</option><?php for($i=1;$i<=4;$i++):?><option value="<?=$i?>" <?=$lab==$i?'selected':''?>><?=$i?></option><?php endfor;?></select></label><label>Máquina <input type="number" name="maq" min="1" value="<?=htmlspecialchars($maq)?>"></label><button class="btn btn-ghost">Filtrar</button></form><table class="hist-table"><thead><tr><th>Quando</th><th>Laboratório</th><th>Máquina</th><th>Tipo</th><th>Título</th><th>Ação</th><th>Usuário</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td class="hist-when"><?=htmlspecialchars(date('d/m/Y H:i',strtotime($e['data_evento'])))?></td><td><?= (int)$e['ID_LAB']?></td><td><?= $e['ID_MAQ']?'#'.(int)$e['ID_MAQ']:'—'?></td><td><?=htmlspecialchars($e['tipo_problema']??'Outro')?></td><td><?=htmlspecialchars($e['titulo'])?></td><td><span class="hist-action <?=$e['acao']==='criada'?'is-created':'is-resolved'?>"><?=htmlspecialchars(acaoLabel($e['acao']))?></span></td><td class="hist-user"><?=htmlspecialchars($e['usuario_nome'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$events):?><p class="empty-state">Nenhum evento encontrado.</p><?php endif;?></div></main></div></body></html>
